commands.powershell:
$ErrorActionPreference='Stop'
$root='results/sdmpc_rl_balanced_goal_20260930/local_budget_v2'
function Read-JsonArtifact($p) { Get-Content -Raw -LiteralPath $p | ConvertFrom-Json }
function Get-RangeStats($values) {
  $m=$values | Measure-Object -Minimum -Maximum -Average
  [ordered]@{min=[double]$m.Minimum;max=[double]$m.Maximum;mean=[double]$m.Average}
}
function Assert-Near($a,$b,$label) { if([math]::Abs($a-$b) -gt 1e-8) { throw "$label differs: $a vs $b" } }
$hashes=[System.Collections.Generic.List[object]]::new()
function Check-Hash($p,$expected) {
  $actual=(Get-FileHash -Algorithm SHA256 -LiteralPath $p).Hash.ToLowerInvariant()
  $hashes.Add([ordered]@{path=$p;sha256=$actual;expected=$expected;match=($actual -eq $expected)})
  if($actual -ne $expected) { throw "Hash mismatch: $p" }
}
Check-Hash "$root/completion.json" '5b6e645f6f6ca64c4f593c52d19ee3ab5bda7ae3c3d31f423d6fae2d2f3ef4a3'
$c=Read-JsonArtifact "$root/completion.json"
Check-Hash "$root/comparison.json" $c.comparison_sha256
$comparison=Read-JsonArtifact "$root/comparison.json"
foreach($name in @('exploration.py','validate.py','frozen_inventory.py','collect.py','local_runtime.py')) {
  $p="work\sdmpc_rl_local_20260930_v2\$name"
  Check-Hash $p $c.plan.identity.local_sources.$p
}
foreach($name in @('budget_controller.py','budget_env.py','budget_runtime.py')) {
  Check-Hash "work/sdmpc_rl_multi_20260929/$name" $c.plan.identity.physical.implementation.$name
}
Check-Hash 'artifacts/sdmpc_budget_baseline_20260929/manifest.json' $c.plan.identity.physical.snapshot_manifest_sha256
$runs=[System.Collections.Generic.List[object]]::new()
$pairs=[System.Collections.Generic.List[object]]::new()
$traces=@{}
$settings=@{}
$receiptHashes=@()
foreach($job in $c.plan.jobs) {
  $key=$job.key
  $dir="$root/$key"
  Check-Hash "$dir/completion.json" $c.child_completion_sha256.$key
  $child=Read-JsonArtifact "$dir/completion.json"
  foreach($o in $child.outputs_sha256.PSObject.Properties) { Check-Hash "$dir/$($o.Name)" $o.Value }
  $t=Read-JsonArtifact "$dir/trace.json"
  $s=Read-JsonArtifact "$dir/summary.json"
  $cfg=Read-JsonArtifact "$dir/settings.json"
  $traces[$key]=$t
  $settings[$key]=$cfg
  if($t.Count -ne 75) { throw "Unexpected rows: $key" }
  $sum=[double]$cfg.warmup_ttt
  for($i=0;$i -lt 75;$i++) {
    $r=$t[$i]
    if($r.control_step -ne $i -or $r.time_sec -ne ($i+6)*180 -or $r.terminated -ne ($i -eq 74) -or $r.truncated) { throw "Row identity: $key/$i" }
    $sum += $r.interval_ttt
    Assert-Near $sum $r.total_ttt "$key cumulative"
    Assert-Near ($r.freeway_ttt+$r.urban_ttt) $r.total_ttt "$key area"
    Assert-Near $r.reward (-$r.interval_ttt/100) "$key reward"
    Assert-Near $r.interval_ttt $s.interval_ttt[$i] "$key summary interval"
    if($i -gt 0) { for($j=0;$j -lt 2;$j++) { Assert-Near $r.action_anchor[$j] $t[$i-1].B_executed[$j] "$key actual anchor" } }
    if(-not $r.execution_check.physical_control_valid -or -not $r.execution_check.budget_feasible -or $r.guard_mode -ne 'physical' -or $r.h3_guard_enabled -or $r.lower_candidate_count -ne 1 -or $null -ne $r.policy_q -or $r.learning.Count -ne 0) { throw "Physical/no-learning: $key/$i" }
  }
  Assert-Near $sum $s.ttt "$key final TTT"
  Assert-Near $t[-1].inventory $s.terminal_inventory "$key inventory"
  $stats=@()
  foreach($j in @(0,1)) {
    $initial=$t[0].action_anchor[$j]
    $stats += [ordered]@{
      coordinate=@('NP','NUF')[$j]; initial=$initial
      requested=(Get-RangeStats @($t | ForEach-Object { $_.B_requested[0][$j] }))
      executed=(Get-RangeStats @($t | ForEach-Object { $_.B_executed[$j] }))
      achieved=(Get-RangeStats @($t | ForEach-Object { $_.G_achieved[$j] }))
      moving_base=(Get-RangeStats @($t | ForEach-Object { $_.exploration_audit.base_before[$j]; $_.exploration_audit.base_after[$j] }))
      final_base=$t[-1].exploration_audit.base_after[$j]
      request_initial_max_abs=(@($t | ForEach-Object { [math]::Abs($_.B_requested[0][$j]-$initial) }) | Measure-Object -Maximum).Maximum
      execution_initial_max_abs=(@($t | ForEach-Object { [math]::Abs($_.B_executed[$j]-$initial) }) | Measure-Object -Maximum).Maximum
      request_moving_max_abs=(@($t | ForEach-Object { [math]::Abs($_.B_requested[0][$j]-$_.exploration_audit.base_before[$j]) }) | Measure-Object -Maximum).Maximum
      execution_moving_max_abs=(@($t | ForEach-Object { [math]::Abs($_.B_executed[$j]-$_.exploration_audit.base_before[$j]) }) | Measure-Object -Maximum).Maximum
      base_initial_max_abs=(@($t | ForEach-Object { [math]::Abs($_.exploration_audit.base_after[$j]-$initial) }) | Measure-Object -Maximum).Maximum
      offset_limited_steps=@($t | Where-Object { $_.exploration_audit.offset_limited[$j] } | ForEach-Object { $_.control_step })
      rate_limited_steps=@($t | Where-Object { $_.exploration_audit.rate_limited[$j] } | ForEach-Object { $_.control_step })
    }
  }
  $ramps=@()
  foreach($name in @('R_D_W','R_D_E','R_F_W','R_F_E')) {
    $maxJump=-1.;$maxStep=-1
    for($i=1;$i -lt 75;$i++) { $d=[math]::Abs($t[$i].control.ramp_metering.$name-$t[$i-1].control.ramp_metering.$name); if($d -gt $maxJump) {$maxJump=$d;$maxStep=$i} }
    $ramps += [ordered]@{name=$name;range=(Get-RangeStats @($t | ForEach-Object {$_.control.ramp_metering.$name}));closed_steps=@($t | Where-Object {$_.control.ramp_metering.$name -le 1e-6} | ForEach-Object {$_.control_step});max_adjacent_jump=$maxJump;jump_step=$maxStep}
  }
  $greenJump=0.;$greenStep=-1;$greenName=''
  $physicalChanges=@()
  for($i=1;$i -lt 75;$i++) {
    $changed=$false
    foreach($field in @('ramp_metering','vsl','green_times','offsets','inflow_outflow_allocation')) {
      foreach($p in $t[$i].control.$field.PSObject.Properties) {
        $delta=[math]::Abs($p.Value-$t[$i-1].control.$field.($p.Name))
        if($delta -gt 1e-6) {$changed=$true}
        if($field -eq 'green_times' -and $delta -gt $greenJump) {$greenJump=$delta;$greenStep=$i;$greenName=$p.Name}
      }
    }
    if($changed) {$physicalChanges += $i}
  }
  $events=@($t | Where-Object {$_.exploration_audit.rebased} | ForEach-Object { [ordered]@{step=$_.control_step;base_before=$_.exploration_audit.base_before;base_after=$_.exploration_audit.base_after;request=$_.B_requested[0];achieved=$_.G_achieved;reason=$_.exploration_audit.rebase_reasons;fallback_reasons=$_.fallback_reasons;candidate_residual=$_.lower_selection_check.original_residual} })
  $runs.Add([ordered]@{
    key=$key;training_seed=$cfg.training_seed;exploration_seed=$cfg.exploration_seed;profile_sha256=$cfg.profile_sha256;gamma=$cfg.contract.gamma;reward_divisor=$cfg.contract.reward_divisor
    ttt=$s.ttt;terminal_inventory=$s.terminal_inventory;warmup_ttt=$cfg.warmup_ttt;statistics=$stats;rebase_events=$events;ramps=$ramps
    physical_change_steps=$physicalChanges;max_green_jump=$greenJump;green_jump_step=$greenStep;green_jump_name=$greenName
    desired_nuf_projection_steps=@($t | Where-Object {$_.exploration_audit.desired_nuf_projected} | ForEach-Object {$_.control_step})
    request_nuf_projection_steps=@($t | Where-Object {$_.exploration_audit.request_nuf_projected} | ForEach-Object {$_.control_step})
    pfo_recovery_steps=@($t | Where-Object {$_.reference_recovery} | ForEach-Object {$_.control_step})
    positive_h3_delta_selected_steps=@($t | Where-Object {$_.selected_TTT -gt $_.reference_TTT+1e-8} | ForEach-Object {$_.control_step})
    terminal_queue_state=$t[-1].queue_state
  })
  if(Test-Path -LiteralPath "$dir/export-receipt.json") {$receiptHashes += [ordered]@{path="$dir/export-receipt.json";sha256=(Get-FileHash -Algorithm SHA256 -LiteralPath "$dir/export-receipt.json").Hash.ToLowerInvariant()}}
}
foreach($pair in $comparison.rows) {
  $sc=$pair.scenario
  $a=$traces["carry/$sc"];$b=$traces["local/$sc"]
  foreach($key in @('profile_sha256','training_seed','warmup_ttt','capacity')) { if($settings["carry/$sc"].$key -ne $settings["local/$sc"].$key) {throw "Pair ${key}: $sc"} }
  $d=@();$inv=@()
  for($i=0;$i -lt 75;$i++) { $d += $b[$i].interval_ttt-$a[$i].interval_ttt; $inv += $b[$i].inventory-$a[$i].inventory; Assert-Near $d[$i] $pair.interval_ttt_delta[$i] "$sc comparison delta" }
  Assert-Near (($d|Measure-Object -Sum).Sum) $pair.training_ttt_delta "$sc total delta"
  foreach($beh in @('carry','local')) {Assert-Near $traces["$beh/$sc"][-1].inventory $pair.$beh.terminal_inventory "$sc comparison inventory"; Assert-Near $traces["$beh/$sc"][-1].total_ttt $pair.$beh.ttt "$sc comparison TTT"}
  $bins=@()
  foreach($bin in @(@(0,14),@(15,25),@(26,49),@(50,74))) {$lo=$bin[0];$hi=$bin[1];$bins += [ordered]@{steps=@($lo,$hi);time_start_sec=($lo+5)*180;time_end_sec=($hi+6)*180;ttt_delta=($d[$lo..$hi]|Measure-Object -Sum).Sum;inventory_delta_end=$inv[$hi]}}
  $maxIndex=0
  for($i=1;$i -lt 75;$i++) {if($d[$i] -gt $d[$maxIndex]) {$maxIndex=$i}}
  $pairs.Add([ordered]@{scenario=$sc;delta=$pair.training_ttt_delta;inventory_ratio=$b[-1].inventory/$a[-1].inventory;interval_delta=$d;inventory_delta=$inv;bins=$bins;positive_intervals=@($d | Where-Object {$_ -gt 1e-8}).Count;max_interval_delta_step=$maxIndex;max_interval_delta=$d[$maxIndex];screen=$pair.coverage_screen_pass})
}
$focus=@()
foreach($i in @(8,9,10,11,12,13,14,15,16,25,26,27,49,74)) {
  $r=$traces['local/sweet_170_w'][$i];$a=$traces['carry/sweet_170_w'][$i]
  $focus += [ordered]@{step=$i;time_sec=$r.time_sec;requested=$r.B_requested[0];executed=$r.B_executed;achieved=$r.G_achieved;base_before=$r.exploration_audit.base_before;base_after=$r.exploration_audit.base_after;desired_offset=$r.exploration_audit.desired_offset;ramps=$r.control.ramp_metering;greens=$r.control.green_times;selection=$r.selection_source;candidate_residual=$r.lower_selection_check.original_residual;interval_delta=$r.interval_ttt-$a.interval_ttt;inventory_delta=$r.inventory-$a.inventory;selected_h3_delta=$r.selected_TTT-$r.reference_TTT}
}
[ordered]@{hashes=$hashes;receipt_hashes=$receiptHashes;runs=$runs;pairs=$pairs;focus170=$focus;integrity_checks='PASS: manifest hashes, 750 JSON rows, paired profiles/seeds/warmup/capacity, interval and area TTT, rewards, anchors, terminal flags, physical/no-learning flags, summaries and comparison reconciled'} | ConvertTo-Json -Depth 22 -Compress

$ErrorActionPreference='Stop'
$root='results/sdmpc_rl_balanced_goal_20260930/local_budget_v2'
function Read-JsonArtifact($p) { Get-Content -Raw -LiteralPath $p | ConvertFrom-Json }
function Total-Values($obj) { [double](($obj.PSObject.Properties.Value | Measure-Object -Sum).Sum) }
$manifest=Read-JsonArtifact 'artifacts/sdmpc_budget_baseline_20260929/manifest.json'
$sourceSuffixes=@('controllers/sensitivity_dmpc.py','simulation/player_cost_accounting.py','models/state.py','sdmpc_externality_ablation_20260923/fixed_policy.py','sdmpc_externality_ablation_20260923/exception_controller.py','sdmpc_externality_ablation_20260923/fixed_controller.py')
$sourceHashes=@()
foreach($suffix in $sourceSuffixes) {
  $matches=@($manifest.files | Where-Object {$_.snapshot_relative.Replace('\','/').EndsWith($suffix)})
  foreach($m in $matches) {
    $p='artifacts/sdmpc_budget_baseline_20260929/'+$m.snapshot_relative
    $actual=(Get-FileHash -LiteralPath $p -Algorithm SHA256).Hash.ToLowerInvariant()
    if($actual -ne $m.sha256) {throw "Source hash mismatch: $p"}
    $sourceHashes += [ordered]@{path=$p;sha256=$actual;expected=$m.sha256;match=$true}
  }
}
$c=Read-JsonArtifact "$root/completion.json"
$terminal=@();$receipts=@();$metering=@()
foreach($job in $c.plan.jobs) {
  $key=$job.key;$dir="$root/$key"
  $cfg=Read-JsonArtifact "$dir/settings.json"
  $t=Read-JsonArtifact "$dir/trace.json"
  $st=$t[-1].plant_state;$net=$cfg.physical_config.network
  $core=0.;$buffers=0.;$transit=0.;$off=0.
  foreach($link in $net.freeway_links) {
    $rho=$st.freeway_density.$link;$lanes=$st.freeway_effective_lanes.$link
    for($i=0;$i -lt $rho.Count;$i++) {$core += [math]::Max(0.,$rho[$i])*$net.freeway_segment_length_km*[math]::Max($lanes[$i],1e-9)}
    foreach($side in @('up','down')) {foreach($rho in $st.('freeway_buffer_'+$side+'_density').$link) {$buffers += $rho*$net.freeway_segment_length_km*$net.freeway_lanes}}
  }
  $offLinks=@($net.off_ramp_storage_link.PSObject.Properties.Value | Select-Object -Unique)
  foreach($p in $net.urban_link_storage_veh.PSObject.Properties) {
    $x=[math]::Max(0.,$p.Value-$st.urban_link_storage.($p.Name))
    if($p.Name -in $offLinks) {$off += $x} else {$transit += $x}
  }
  $parts=[ordered]@{core=$core;ramps=(Total-Values $st.ramp_queue);origins=(Total-Values $st.mainline_origin_queue);urban_movements=(Total-Values $st.urban_movement_queue);urban_transit=$transit;offramp_storage=$off;freeway_buffers=$buffers}
  $total=($parts.Values | Measure-Object -Sum).Sum
  if([math]::Abs($total-$t[-1].inventory) -gt 1e-8) {throw "Inventory mismatch $key"}
  $terminal += [ordered]@{key=$key;parts=$parts;total=$total}
  $maxDiff=0.
  foreach($r in $t) {
    if($null -eq $r.plant_log.diagnostics.total_metering_flow) {throw "Missing actual metering $key"}
    $maxDiff=[math]::Max($maxDiff,[math]::Abs($r.G_achieved[1]-$r.plant_log.diagnostics.total_metering_flow))
  }
  $metering += [ordered]@{key=$key;max_achieved_vs_plant_metering_difference=$maxDiff}
  if(Test-Path -LiteralPath "$dir/export-receipt.json") {
    $rc=Read-JsonArtifact "$dir/export-receipt.json";$comp=Read-JsonArtifact "$dir/completion.json"
    foreach($o in $rc.output_sha256.PSObject.Properties) {if($comp.outputs_sha256.($o.Name) -ne $o.Value) {throw "Receipt output mismatch $key"}}
    $receipts += [ordered]@{key=$key;output_hashes_match=$true;checkpoint_authoritative=$rc.checkpoint_authoritative;convergence_claim=$rc.convergence_claim;physical_or_training_change=$rc.physical_or_training_change}
  }
}
$t=Read-JsonArtifact "$root/local/sweet_170_w/trace.json"
$r=$t[10];$anchor=$r.action_anchor[1];$base=6000.
$realized=$t[9].B_executed[1]-$base
$offset=[math]::Max(-500.,[math]::Min(500.,.8*$realized+100.*$r.exploration_audit.noise[1]))
$desired=[math]::Max(0.,[math]::Min(6000.,$base+$offset))
$act=[single]([math]::Max(-1.,[math]::Min(1.,($desired-$anchor)/1000.)))
$request=[math]::Max(0.,[math]::Min(6000.,$anchor+1000.*[double]$act))
[ordered]@{source_hashes=$sourceHashes;terminal=$terminal;receipts=$receipts;metering=$metering;first_divergence_arithmetic=[ordered]@{step=10;noise=$r.exploration_audit.noise[1];realized_offset=$realized;desired_offset=$offset;desired_budget=$desired;action_float32=[double]$act;request=$request;old_request=$r.B_requested[0][1];difference=$request-$r.B_requested[0][1];no_physical_counterfactual_computed=$true}} | ConvertTo-Json -Depth 8 -Compress

$root='results/sdmpc_rl_balanced_goal_20260930/local_budget_v2'
$c=Get-Content -Raw -LiteralPath "$root/completion.json" | ConvertFrom-Json
$out=@()
foreach($job in $c.plan.jobs) {
  $t=Get-Content -Raw -LiteralPath "$root/$($job.key)/trace.json" | ConvertFrom-Json
  $ramps=@()
  foreach($name in @('R_D_W','R_D_E','R_F_W','R_F_E')) {
    $field='ramp_metering_release_actual_'+$name+'_veh'
    $values=@($t | ForEach-Object {$_.plant_log.diagnostics.$field})
    $ramps += [ordered]@{name=$name;min=($values|Measure-Object -Minimum).Minimum;closed_steps=@($t|Where-Object {$_.plant_log.diagnostics.$field -le 1e-6}|ForEach-Object {$_.control_step})}
  }
  $out += [ordered]@{key=$job.key;actual_releases=$ramps;focus=@($t|Where-Object {$_.control_step -in @(13,14,15,16,17)}|ForEach-Object {[ordered]@{step=$_.control_step;D_W=$_.plant_log.diagnostics.ramp_metering_release_actual_R_D_W_veh;D_E=$_.plant_log.diagnostics.ramp_metering_release_actual_R_D_E_veh}})}
}
$out | ConvertTo-Json -Depth 7 -Compress
